using EFootwear.Domain.Common;

namespace EFootwear.Domain.CashManagement;

/// <summary>
/// The end-of-day cash count of one store (docx 3.6 Cash Calculator, 3.7 View Cash Detail). Table: cash.cash_counts, unique per
/// store and day. CountedCash is always the sum of denomination x number of notes, computed on the server. ExpectedCash is
/// the cash the books say the store holds (the "Computer Cash"); the Difference is generated by the database.
/// </summary>
public sealed class CashCount : IHasRowVersion
{
    public Guid CompanyId { get; set; }
    public Guid Id { get; set; }
    public Guid StoreId { get; set; }
    public DateOnly CountDate { get; set; }
    public long OpeningCash { get; set; }
    public long ExpectedCash { get; set; }
    public long CountedCash { get; set; }

    /// <summary>CountedCash - ExpectedCash, computed by the database (read only).</summary>
    public long DifferenceAmount { get; set; }

    public Guid? CountedBy { get; set; }
    public string? Note { get; set; }

    /// <summary>Figures typed in by the person counting, as in the old screen. Net Sale is not stored (formula not documented).</summary>
    public long? PaymentsAmount { get; set; }

    public long? CreditSalesAmount { get; set; }
    public long? CreditReceivedAmount { get; set; }
    public DateTimeOffset CreatedAt { get; set; }
    public Guid? CreatedBy { get; set; }
    public long RowVersion { get; set; }
}
